update public."Goal_master" set "Role"='Admin';
do $qa$ declare n int;begin
select count(*) into n from (select "Goal ID","Goal Name","Goal Description","Total Indicators","Total Initiatives" from public."Goal_master" where (false or "Role"='All') order by "Goal ID") q;if n<>0 then raise exception 'Public goals leaked private records';end if;
select count(*) into n from (select "Goal ID","Goal Name","Goal Description","Total Indicators","Total Initiatives" from public."Goal_master" where (true or "Role"='All') order by "Goal ID") q;if n=0 then raise exception 'Authenticated goals omitted private records';end if;
select count(*) into n from (select m."Indicator ID",m."Indicator Name",m."Indicator_short_name",m."Indicator Type",m."Goal ID",m."KPI Nature" from public."Indicator_master" m join public."Goal_master" g on g."Goal ID"=m."Goal ID" where (false or (m."Role"='All' and g."Role"='All')) order by m."Indicator ID") q;if n<>0 then raise exception 'Public indicators leaked private records';end if;
