select count(*) into n from (select d."Goal ID",d."Indicator ID",d."Indicator Name",d."School Year",d."Category",d."Student Group",d."Value 1",d."Value 2",d."Value 3",d."Target 1",d."Target 2",d."Target 3",d."School" from public."Indicator_Data" d join public."Indicator_master" m on m."Indicator ID"=d."Indicator ID" and m."Goal ID"=d."Goal ID" join public."Goal_master" g on g."Goal ID"=m."Goal ID" where (false or (d."Role"='All' and m."Role"='All' and g."Role"='All')) order by d."Indicator ID",d."School Year",d."Category",d."Student Group" limit 300) q;if n<>0 then raise exception 'Public indicatorData leaked private records';end if;
